"use client";

import { useRef, useState } from "react";
import { signIn } from "next-auth/react";
import { Button } from "@/components/ui/button";

export function CheckoutButton({ signedIn }: { signedIn: boolean }) {
  const attemptKey = useRef<string | null>(null);
  const pending = useRef(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  async function openCheckout() {
    if (pending.current) return;
    pending.current = true;
    setBusy(true);
    setError("");
    try {
      if (!signedIn) {
        await signIn("google", { redirectTo: "/pricing" });
        return;
      }
      attemptKey.current ??= crypto.randomUUID();
      const response = await fetch("/api/billing/checkout", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          plan: "paid_monthly",
          idempotencyKey: attemptKey.current,
        }),
      });
      const result = await response.json();
      if (!response.ok) {
        if (result.code === "CHECKOUT_ATTEMPT_FINISHED")
          attemptKey.current = null;
        throw new Error(result.error || "Could not open checkout.");
      }
      if (typeof result.checkoutUrl !== "string" || !result.checkoutUrl)
        throw new Error("Could not open checkout.");
      window.location.assign(result.checkoutUrl);
    } catch (error) {
      setError(
        error instanceof Error ? error.message : "Could not open checkout.",
      );
    } finally {
      pending.current = false;
      setBusy(false);
    }
  }

  return (
    <>
      <Button
        type="button"
        className="upgrade-shine relative isolate overflow-hidden"
        disabled={busy}
        aria-busy={busy}
        onClick={() => void openCheckout()}
      >
        {busy ? "Opening checkout…" : "Upgrade to Premium"}
      </Button>
      {error && <p role="alert">{error}</p>}
    </>
  );
}
